encodeURI('a b&c=d/e')           // 'a%20b&c=d/e'
encodeURIComponent('a b&c=d/e')  // 'a%20b%26c%3Dd%2Fe'

encodeURI('https://example.com/search?q=a b&lang=en')
// 'https://example.com/search?q=a%20b&lang=en'

encodeURIComponent('café')
// 'caf%C3%A9'

encodeURI('100%')
// '100%25'

const term = 'fish & chips';
const page = 2;

const url = `https://api.example.com/search?q=${encodeURIComponent(term)}&page=${encodeURIComponent(page)}`;
// 'https://api.example.com/search?q=fish%20%26%20chips&page=2'

const term = 'salt & pepper';

const bad = `https://example.com/search?q=${encodeURI(term)}`;
// 'https://example.com/search?q=salt%20&%20pepper'
// The server reads q='salt ' and a separate parameter ' pepper' with no value.

const good = `https://example.com/search?q=${encodeURIComponent(term)}`;
// 'https://example.com/search?q=salt%20%26%20pepper'

try {
  encodeURIComponent('\uD800');
} catch (e) {
  console.log(e.name, e.message); // URIError URI malformed
}

const clean = 'emoji \uD83D'.toWellFormed(); // 'emoji \uFFFD'
encodeURIComponent(clean);               // 'emoji%20%EF%BF%BD'
